    pm.response.to.have.status(parseInt(expected));
});

var credentials = btoa("user:pass");
pm.request.headers.add({
    key: "Authorization",
    value: "Basic " + credentials
});

var users = pm.response.json().users;
var ids = users.map(u => u.id);
pm.environment.set("ids", JSON.stringify(ids));

pm.test("Status and body check", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.text()).to.include("OK");
});

var counter = parseInt(pm.environment.get("retryCount") || "0");
counter++;
pm.environment.set("retryCount", counter.toString());
if (counter < 3) {
    postman.setNextRequest("Retry Request");
} else {
    postman.setNextRequest(null);
}

var data = pm.response.json();
if (data.next_page) {
    pm.environment.set("nextUrl", data.next_page);
}

