    var expected = parseInt(pm.iterationData.get("statusCode"));
    pm.response.to.have.status(expected);
});

var body = pm.request.body.raw;
var secret = pm.environment.get("apiSecret");
var signature = CryptoJS.HmacSHA256(body, secret).toString();
pm.environment.set("signature", signature);

var timeout = 2000;
if (pm.info.requestName) {
    timeout = 5000; // more lenient in monitors
}
pm.test("Response time OK", function () {
    pm.expect(pm.response.responseTime).to.be.below(timeout);
});

